-- [3 col(s)]. Multi-active: compared per (key, child key); latest = max LOAD_DATETIME
-- per member.
----------------------------------------------------------------------------------------
-- DM-H1 (a) MAXIMUS SAT_AUG_RISK_TRAVEL_COVER_TERMS: HASHDIFF not recomputable -- see note



